import { marketLabel, type NbaMarket } from "../nba-markets";
import type { SortColumn } from "./sort";

export const NBA_LINE_HINT =
  "One row per player, at the line the most books price. The engine picks the line and each side's best price.";

// Snapshot disagreement, separate from a book's exact quote comparison.
export const WIDTH_HINT =
