export const SEASON_HINT = "Per-game average in this stat this season.";

export const LAST_TEN_HINT =
  "The player's last 10 played games against this line, oldest first, back into last season past the hairline. A lit bar went over, an outlined one landed on the line. The count is the engine's: overs out of games decided.";

export const CLEARED_HINT =
  "How often the player went over this line this season, the engine's rate. Hover a rate for the games behind it.";

export const ALLOWED_HINT =
  "What his opponent allows per game in this stat this season, and its league rank: 1st is the fewest. Under 10 games, last season's sits under it. A muted figure is on few games, or is threes, and says little.";

const COLUMN_LABEL: Record<Exclude<SortColumn, "allowed">, string> = {
  l5: "L5",
  season: "SZN",
  last10: "LAST 10",
  cleared: "CLEARED SZN",
  line: "LINE",
  overPrice: "OVER",
  underPrice: "UNDER",
};

// ALLOWED is named for the market, so its label is built per board.
export function columnLabel(market: NbaMarket, column: SortColumn): string {
  return column === "allowed"
    ? `${marketLabel(market)} ALLOWED`
    : COLUMN_LABEL[column];
}
