import { defaultQuoteBook, isShop } from "@/features/book-movement";
import { bookLabel } from "@/shared/utils/books";
import { formatSlateDay } from "../format";
import { marketLabel, type NbaMarket } from "../nba-markets";
import type { LiveNbaGame } from "../nba-slate.model";
import type { NbaPlayerStats } from "../use-nba-player-stats";
import type { NbaProps } from "../use-nba-props";
import type { NbaTeamDefense } from "../use-nba-team-defense";
import { selectBoardScope } from "./select-board-scope";
import { type PropBoardRow, selectPropRows } from "./select-prop-rows";
import { type SortStack, sortRows } from "./sort";

export type PropBoardView = {
  // The quote book in force: the URL's, or the default for the books served.
  quoteBook: string | null;
  // The drawn rows, in the order on glass.
  rows: PropBoardRow[];
  gameCount: number;
  // Rows whose player the stats read never asked about, named in a strip.
  // Empty while the read is pending or failed: those name themselves.
  noPack: PropBoardRow[];
  // A failed props refresh with rows held: the strip says the prices may be
  // stale, and the board keeps its rows. Computed once here (AGENTS.md: one
  // condition, one boolean), because `error` reads the same `held`.
  refreshFailed: boolean;
  pending: boolean;
  error: { text: string; retry: () => void } | null;
  // The read has answered with rows or none, so the counts can show.
  answered: boolean;
  emptyText: string;
  // Every game in scope has tipped: the meta strip says the prices are the
  // last ones before tip.
  nothingToTip: boolean;
};

// What the board draws of its reads. The desktop board and the phone's both
// call this, so the two cannot draw different rows, fail differently or say a
// different empty text.
export function selectBoardView({
  date,
  props,
  stats,
  defense,
  games,
  selectedId,
  market,
  book,
  stack,
}: {
  // The served day, for the empty text.
  date: string;
  props: NbaProps;
  stats: NbaPlayerStats;
  defense: NbaTeamDefense;
  // Every game on the rail.
  games: LiveNbaGame[];
  selectedId: number | null;
  market: NbaMarket;
  book: string | undefined;
  stack: SortStack;
}): PropBoardView {
  const quoteBook = book ?? defaultQuoteBook(props.books);
  const scope = selectBoardScope(games, selectedId);
  const rows = sortRows(
    selectPropRows({
      games: scope.games,
      byEvent: props.byEvent,
      market,
      book: quoteBook,
      packs: stats.byId,
      defense: defense.byTeam,
    }),
    stack,
  );
  const gameCount = new Set(rows.map((row) => row.eventId)).size;

  // Pending has not answered yet, and a failed read names itself in its own
  // strip. Only a player the read never asked about is left.
  const noPack =
    stats.isPending || stats.isError
      ? []
      : rows.filter((row) => row.pack === null);

  const pending = props.isPending;
  // TanStack v5 keeps `data` and sets `isError` on a failed refetch, so the
  // error guards on held rows: a failed refresh must not blank the board.
  const held = props.byEvent.size > 0;
  const error =
    props.isError && !held
      ? { text: "Props read failed", retry: props.retry }
      : null;

  const label = marketLabel(market);
  const upcoming =
    selectedId === null && !scope.nothingToTip ? "upcoming " : "";
  // A quote in the scope means another book prices it, so an empty board is the
  // chosen book's gap; with none anywhere it is the day's, and naming the book
  // would blame it.
  const quotedElsewhere = scope.games.some(
    (game) => (props.byEvent.get(game.event_id)?.quotes.length ?? 0) > 0,
  );
  const atBook =
    quoteBook === null || isShop(quoteBook) || !quotedElsewhere
      ? ""
      : ` at ${bookLabel(quoteBook)}`;
  const where =
    selectedId === null ? `on ${formatSlateDay(date)}` : "for this game";

  return {
    quoteBook,
    rows,
    gameCount,
    noPack,
    refreshFailed: props.isError && held,
    pending,
    error,
    answered: !pending && error === null,
    emptyText: `No ${upcoming}${label} props${atBook} ${where}`,
    nothingToTip: scope.nothingToTip,
  };
}
