import type { ReactElement } from "react";
import type { NbaPlayerStats } from "../use-nba-player-stats";
import type { NbaProps } from "../use-nba-props";
import type { NbaTeamDefense } from "../use-nba-team-defense";
import { FailedReadStrip } from "./failed-read-strip";
import { PackGapStrip } from "./pack-gap-strip";
import type { PropBoardView } from "./select-board-view";

// The strips above a board whose rows are still on glass: one per read that
// failed, each with that read's own retry, and the players the engine cannot
// answer for. The desktop board and the phone's both render it, so a failure
// reads the same words on either.
export function BoardStrips({
  view,
  props,
  stats,
  defense,
}: {
  view: PropBoardView;
  props: NbaProps;
  stats: NbaPlayerStats;
  defense: NbaTeamDefense;
}): ReactElement {
  return (
    <>
      {view.refreshFailed && (
        <FailedReadStrip
          text="Props refresh failed — prices may be stale"
          retry={props.retry}
        />
      )}
      {stats.isError && (
        <FailedReadStrip text="Stat pack read failed" retry={stats.retry} />
      )}
      {defense.isError && (
        <FailedReadStrip
          text="Opponent defense read failed"
          retry={defense.retry}
        />
      )}
      {view.noPack.length > 0 && (
        <PackGapStrip
          players={view.noPack.map(
            (row) => row.playerName ?? `#${row.playerId}`,
          )}
        />
      )}
    </>
  );
}
