(async () => {
  const sleep = (ms) => new Promise(r => setTimeout(r, ms));
  const cards = [...document.querySelectorAll('.nba-card-grid')].slice(0, 60);
  let worst = -Infinity, worstWho = null, opened = 0, sideways = 0;
  for (const card of cards) {
    card.click();
    await sleep(60);
    const s = card.nextElementSibling;
    if (!s || !s.matches('section.nba-mobile-pack')) continue;
    opened++;
    const r = s.getBoundingClientRect();
    const right = r.right - parseFloat(getComputedStyle(s).paddingRight);
    for (const t of s.querySelectorAll('table')) {
      const past = Math.round(t.getBoundingClientRect().right - right);
      if (past > worst) { worst = past; worstWho = card.querySelector('button')?.getAttribute('aria-label'); }
    }
    if (document.documentElement.scrollWidth > document.documentElement.clientWidth) sideways++;
  }
  return JSON.stringify({ width: innerWidth, packsOpened: opened, worstTablePastEdge: worst, worstPack: worstWho, pageScrolledSidewaysWhileOpen: sideways });
})()
